/*:
 * @author Toby Yasha
 * @plugindesc Removes blur from the battle background.
 * @target MZ
 *
 * @help
 *
 * Feel free to use this however you want, no credit needed.
 *
 */

(function() {

const Spriteset_Battle_createBackground = Spriteset_Battle.prototype.createBackground;
Spriteset_Battle.prototype.createBackground = function() {
    Spriteset_Battle_createBackground.call(this);
    this._backgroundSprite.filters = null;
};

})();

